mapper.select:
select t.gift_amount giftAmount,t.order_type orderType,t.pay_order_id payOrderId,t.prime_rate
primeRate,t.receivable_amount receivableAmount,t.discount_amount discountAmount,t.remark,t.status_cd
statusCd,t.received_amount receivedAmount,t.owner_id ownerId,t.payer_obj_name payerObjName,t.ext_order_id
extOrderId,t.owner_name ownerName,t.late_amount lateAmount,t.cashier_id cashierId,t.acct_amount
acctAmount,t.state,t.community_id communityId,t.payer_obj_type payerObjType,t.cashier_name
cashierName,t.payer_obj_id payerObjId,t.create_time createTime,td2.`name` primeRateName,td.name stateName,
t.prime_file primeFile
from pay_fee_order t
left join t_dict td on t.state = td.status_cd and td.table_name = 'pay_fee_detail' and td.table_columns = 'state'
left join t_dict td2 on t.`prime_rate` = td2.`status_cd` AND
td2.`table_name` = 'pay_fee_detail' AND td2.`table_columns` = 'prime_rate'
where 1 =1

    and t.gift_amount= #{giftAmount}


    and t.order_type= #{orderType}


    and t.pay_order_id= #{payOrderId}


    and t.prime_rate= #{primeRate}


    and t.receivable_amount= #{receivableAmount}


    and t.discount_amount= #{discountAmount}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.received_amount= #{receivedAmount}


    and t.owner_id= #{ownerId}


    and t.payer_obj_name= #{payerObjName}


    and t.ext_order_id= #{extOrderId}


    and t.owner_name= #{ownerName}


    and t.late_amount= #{lateAmount}


    and t.cashier_id= #{cashierId}


    and t.acct_amount= #{acctAmount}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.payer_obj_type= #{payerObjType}


    AND t.cashier_name LIKE CONCAT('%', #{cashierName}, '%')


    and t.payer_obj_id= #{payerObjId}


    and t.create_time >= #{startTime}


    and t.create_time <= #{endTime}

order by t.create_time desc

    limit #{page}, #{row}

