    , t.gift_amount= #{giftAmount}


    , t.order_type= #{orderType}


    , t.prime_rate= #{primeRate}


    , t.receivable_amount= #{receivableAmount}


    , t.discount_amount= #{discountAmount}


    , t.remark= #{remark}


    , t.received_amount= #{receivedAmount}


    , t.owner_id= #{ownerId}


    , t.payer_obj_name= #{payerObjName}


    , t.ext_order_id= #{extOrderId}


    , t.owner_name= #{ownerName}


    , t.late_amount= #{lateAmount}


    , t.cashier_id= #{cashierId}


    , t.acct_amount= #{acctAmount}


    , t.state= #{state}


    , t.payer_obj_type= #{payerObjType}


    , t.cashier_name= #{cashierName}


    , t.payer_obj_id= #{payerObjId}

where 1=1
   and t.pay_order_id= #{payOrderId}

    and t.community_id= #{communityId}

